import ledger


AMOUNT_FACTOR = 100


def _encode(cents):
    if not isinstance(cents, int):
        raise ValueError
    sign = '+' if cents >= 0 else '-'
    s = str(abs(cents))
    check = sum(int(d) for d in s) % 10
    return f"{sign}{s}#{check}"


def transfer(acct, cents, reason):
    encoded = _encode(cents)
    try:
        return ledger.post(acct, encoded, memo=reason)
    except ledger.PostError:
        raise

